import{_ as s,c as t,o as a,ag as n}from"./chunks/framework.Bzez9NG9.js";const o="/space/img/access_list.png",i="/space/img/invite_new_user.png",r="/space/img/new_access_token.png",c="/space/img/security_roles.png",l="/space/img/edit_create_role.png",y=JSON.parse('{"title":"Access","description":"Manage SPACE invitations, access tokens, and security roles that control access to platform modules.","frontmatter":{"title":"Access","description":"Manage SPACE invitations, access tokens, and security roles that control access to platform modules.","keywords":["IBMid","service account","module permissions"],"outline":"deep"},"headers":[],"relativePath":"doc/configuration/access.md","filePath":"doc/configuration/access.md"}'),d={name:"doc/configuration/access.md"};function p(u,e,m,g,h,_){return a(),t("div",null,e[0]||(e[0]=[n('<h1 id="access" tabindex="-1">Access <a class="header-anchor" href="#access" aria-label="Permalink to &quot;Access&quot;">​</a></h1><p>The <strong>Access</strong> tab in SPACE settings controls who can sign in to SPACE and which modules they can use. It manages SPACE invitations, access tokens, and security roles. To analyze IBM Planning Analytics (TM1) user permissions, open the standalone <a href="./../planning-analytics/users-and-access.html">Users and access</a> module.</p><p><img src="'+o+'" alt="Access list" data-zoomable=""></p><p>Each row shows the user or service account, current status, and assigned role(s). Use the action buttons to invite a new user, create a token, or manage roles.</p><h2 id="inviting-users" tabindex="-1">Inviting users <a class="header-anchor" href="#inviting-users" aria-label="Permalink to &quot;Inviting users&quot;">​</a></h2><p>Click <strong>Invite user</strong> to send an email invitation.</p><p><img src="'+i+'" alt="Invite user modal" data-zoomable=""></p><p>Provide:</p><ul><li><strong>Email</strong> – the IBMid or corporate email that signs into PAW.</li><li><strong>IBM PA host</strong> – the PA environment the invite applies to.</li><li><strong>Permissions</strong> – toggle <strong>Admin access</strong> (requires TM1 ADMIN group) or select one or more custom roles.</li><li><strong>Expiry date</strong> – optional date to auto-disable the invite.</li></ul><h2 id="creating-access-tokens" tabindex="-1">Creating access tokens <a class="header-anchor" href="#creating-access-tokens" aria-label="Permalink to &quot;Creating access tokens&quot;">​</a></h2><p>Service accounts and automations authenticate with personal access tokens.</p><p><img src="'+r+'" alt="Create access token modal" data-zoomable=""></p><p>Specify a token name, select the roles or admin access required, and set an expiry date. After creation, copy the token once and store it securely; SPACE does not display it again.</p><h2 id="managing-security-roles" tabindex="-1">Managing security roles <a class="header-anchor" href="#managing-security-roles" aria-label="Permalink to &quot;Managing security roles&quot;">​</a></h2><p>Roles bundle permissions so you can reuse them when inviting users or creating tokens.</p><p><img src="'+c+'" alt="Security roles list" data-zoomable=""></p><p>Use <strong>New role</strong> to define a role name and the modules it grants access to. Editing an existing role immediately updates every user or token that references it. Delete unused roles to keep the list tidy.</p><p><img src="'+l+'" alt="Role editor modal" data-zoomable=""></p><p>Roles store only a name and the set of module permissions—keep names descriptive (e.g., “Audit Log Viewer”) so administrators can quickly identify the intended access level.</p><h2 id="connection-and-tm1-access" tabindex="-1">Connection and TM1 access <a class="header-anchor" href="#connection-and-tm1-access" aria-label="Permalink to &quot;Connection and TM1 access&quot;">​</a></h2><p>Connection-specific restrictions are configured under <a href="./connections.html">Connections</a>. To inspect a TM1 user&#39;s groups and data permissions, use <a href="./../planning-analytics/users-and-access.html">Users and access</a>.</p>',21)]))}const k=s(d,[["render",p]]);export{y as __pageData,k as default};
